import{r as t}from"./request-CA8KvjyH.js";const s=e=>encodeURIComponent(String(e||"")),n={getList(e){return t.get("/mails",{params:e})},getDetail(e){return t.get(`/mails/${s(e)}`)},mediaUrl(e,r){const a=encodeURIComponent(localStorage.getItem("auth_token")||"");return`/api/mails/${s(e)}/media/${encodeURIComponent(String(r||""))}?token=${a}`},saveDraft(e,r){return t.post(`/mails/${s(e)}/save`,{body:r})},approve(e){return t.post(`/mails/${s(e)}/approve`)},reject(e,r){return t.post(`/mails/${s(e)}/reject`,{reason:r})},delete(e){return t.post("/mails/delete",{message_ids:e})},getStats(){return t.get("/mails/stats")}};export{n as m};
